<?php
namespace App\Models;
use Illuminate\Foundation\Auth\User as Authenticatable; use Illuminate\Contracts\Auth\MustVerifyEmail; use Illuminate\Database\Eloquent\Relations\BelongsToMany; use Illuminate\Database\Eloquent\Relations\HasMany; use Illuminate\Database\Eloquent\Relations\HasOne; use Illuminate\Database\Eloquent\Concerns\HasUuids; use Illuminate\Notifications\Notifiable; use Laravel\Sanctum\HasApiTokens;
class User extends Authenticatable implements MustVerifyEmail { use HasApiTokens, HasUuids, Notifiable; protected $fillable=['name','email','password','email_verified_at','country_code','phone_e164','account_status','user_type']; protected $hidden=['password','remember_token']; public $incrementing=false; protected $keyType='string'; protected function casts(): array { return ['email_verified_at'=>'datetime','password'=>'hashed','is_active'=>'boolean']; } public function wallets(): HasMany { return $this->hasMany(Wallet::class); } public function customerProfile(): HasOne { return $this->hasOne(CustomerProfile::class); } public function roles(): BelongsToMany { return $this->belongsToMany(Role::class,'role_assignments'); } public function hasRole(string $role): bool { return $this->roles()->where('name',$role)->exists(); } public function loginActivities(): HasMany { return $this->hasMany(LoginActivity::class); } public function notifications(): HasMany { return $this->hasMany(Notification::class,'notifiable_id')->where('notifiable_type',self::class); } public function supportTickets(): HasMany { return $this->hasMany(SupportTicket::class,'user_id'); } }
